Ext.define('ChartHTML.view.Lib.ViewUtils', {
    extend: 'Ext.Base',

    themeDefined: false,

    getAxeFromSpec: function(typeAxe, orientation) {
        if (orientation === "vertical"){
            if (typeAxe == "numeric1")
                return "left";
            else
                return "right";
        }
        else{
            if (typeAxe == "numeric1")
                return "right";
            else
                return "left";
        }

    },

    mapChartType: function(type, mode, show3d) {
        switch (type){
            case "column":
            case "bar":
                return show3d && mode !== "overlaid" ? "bar3d" : "bar";
            case "line":
                return "line";
            case "area":
                return "area";
            case "pie":
                return show3d ?  "pie3d" : "pie";
            default:
                return type;
        }
    },

    RendererAxi: function(label, layout, lastLabel) {
        var ds = Ext.util.Format.decimalSeparator,
            ts = Ext.util.Format.thousandSeparator,
            text ;


        Ext.util.Format.decimalSeparator = ',';
        Ext.util.Format.thousandSeparator = '.';

        text = Ext.util.Format.number(label, "0,00");

        Ext.util.Format.decimalSeparator = ds;
        Ext.util.Format.thousandSeparator = ts;

        return text;

    },

    defineTheme: function(colors) {
        if (this.themeDefined === false){
            this.themeDefined = true;


            Ext.chart.theme.ISChartTheme = Ext.extend(Ext.chart.theme.Base, {
                constructor: function(config) {
                    Ext.chart.theme.Base.prototype.constructor.call(this, Ext.apply({
                        colors: colors
                    }, config));
                }
            });

        }
    },

    renderGenericTooltip: function(component) {
        Ext.create('Ext.tip.ToolTip', {
            target: component.getEl(),
            trackMouse: true,
            cls: 'theme_default_font  theme_font_size_value theme_font_color_1 tooltipCss',
            html: component.opts.text
        });
    },

    interpolate: function(lambda, minSrc, maxSrc, minDst, maxDst) {
        var value = Math.min(1, (lambda - minSrc) / (maxSrc - minSrc));
        return minDst + (maxDst - minDst) * Math.max(0, value);
    }

});